new_s44_block = r"""\subsection{Unified Young--Gr\"{o}nwall--Lyapunov Extrapolation Bound and Per-Seed Spectral Norm Audit}
While Theorem~\ref{thm:uub} guarantees that individual trajectories remain globally bounded for any $\alpha_{\mathrm{eff}} > 0$, bounding the terminal error between the $M$-step Strang-split state $\hat{z}^{(M)} = \Psi_{\delta t}^{(M)}(z_k)$ ($\delta t = h_k / M$) and a continuous-time target trajectory $z^*(t_k + h_k) = [q^*(t_k + h_k); \dot{q}^*(t_k + h_k)]$ requires separating the continuous-time ODE tracking error $e(t) = [\delta q(t); \delta p(t)] = \hat{z}^{\mathrm{exact}}(t) - z^*(t)$ from the numerical Strang-splitting discretization error $E_{\mathrm{disc}}(h_k, \delta t) \triangleq \|\hat{z}^{(M)} - \hat{z}^{\mathrm{exact}}(t_k + h_k)\|_2$ via the triangle inequality:
\begin{equation}
\big\|\hat{z}^{(M)} - z^*(t_k + h_k)\big\|_2 \le \big\|e(t_k + h_k)\big\|_2 + E_{\mathrm{disc}}(h_k, \delta t).
\label{eq:tri_split_err}
\end{equation}

\textbf{Construction of the Continuous-Time $C^2$ Target Trajectory and Certified Residual Supremum:} On each telemetry gap window $w$ with integration horizon $h_w = \min(\tilde{\Delta t}_w, h_{\max})$ ($s = t - t_w \in [0, h_w]$), the target encoder $f_\xi$ produces endpoint states $z_w^* = f_\xi(\tilde{x}_w) = [q_{k,w}^*; \dot{q}_{k,w}^*]$ at $s = 0$ and $\tilde{z}_{w+1} = f_\xi(\tilde{x}_{w+1}) = [\tilde{q}_{w+1,w}; \dot{\tilde{q}}_{w+1,w}]$ at $t_{w+1}$, defining secant velocity $v_{\mathrm{sec},w} = \frac{\tilde{q}_{w+1,w} - q_{k,w}}{\max(1.0, 4\tilde{\Delta t}_w)}$ and constant secant acceleration $a_{\mathrm{sec},w} = \frac{\dot{\tilde{q}}_{w+1,w} - \dot{q}_{k,w}}{\max(1.0, 4\tilde{\Delta t}_w)}$. The canonical constant-acceleration kinematic interpolant on $s \in [0, h_w]$ is:
\begin{equation}
q_w^*(s) = q_{k,w}^* + s\, v_{\mathrm{sec},w} + \frac{1}{2} s^2 a_{\mathrm{sec},w}, \quad \dot{q}_w^*(s) = v_{\mathrm{sec},w} + s\, a_{\mathrm{sec},w},
\label{eq:c2_target}
\end{equation}
which belongs to $C^\infty([0, h_w], \mathbb{R}^d) \subset C^2([0, h_w], \mathbb{R}^d)$ with $\ddot{q}_w^*(s) \equiv a_{\mathrm{sec},w}$. Along $q_w^*(s)$, the Euler--Lagrange ODE residual is $r_{\mathrm{model},w}(s) = a_{\mathrm{sec},w} + \gamma \dot{q}_w^*(s) - F_{\mathrm{tot}}(q_w^*(s))$. Partitioning $W_{\mathrm{pot}}$ into its convex modes ($s_i = +1 > 0$) and non-convex modes ($s_i = -0.65 < 0$, submatrix $W_{\mathrm{pot},-} \in \mathbb{R}^{d \times 3}$) defines the two-sided Lipschitz constant $L_{\mathrm{nl,full}}$ and one-sided non-convex constant $L_{\mathrm{nl}}^{(-)}$:
\begin{align}
L_{\mathrm{nl,full}} &= \underbrace{\frac{1}{d}\|W_{\mathrm{pot}}\|_2^2}_{L_{V,\mathrm{full}}} + c_f \beta_q, \label{eq:lnl_full} \\
L_{\mathrm{nl}}^{(-)} &= \underbrace{\frac{0.65}{d}\|W_{\mathrm{pot},-}\|_2^2}_{L_{V,-}} + c_f \beta_q, \label{eq:lnl_neg}
\end{align}
where $c_f \beta_q = 0.1575$ and $\|DF_{\mathrm{tot}}(q)\|_2 \le L_F \triangleq \alpha_{\mathrm{eff}} + L_{\mathrm{nl,full}}$. Because $\sup_{s \in [0, h_w]}\|\frac{d}{ds}r_{\mathrm{model},w}(s)\|_2 \le L_{r,w} \triangleq \gamma\|a_{\mathrm{sec},w}\|_2 + L_F(\|v_{\mathrm{sec},w}\|_2 + h_w\|a_{\mathrm{sec},w}\|_2)$, evaluating $\|r_{\mathrm{model},w}(s_j)\|_2$ on $K = 100$ uniform grid points $s_j = \frac{j}{K}h_w$ and adding the exact Taylor envelope remainder $L_{r,w}\frac{h_w}{2K}$ yields the \textbf{continuum-certified within-window residual supremum}:
\begin{equation}
\varepsilon_{\mathrm{mod},w}^{\sup} \triangleq \max_{0 \le j \le K}\big\|r_{\mathrm{model},w}(s_j)\big\|_2 + L_{r,w}\frac{h_w}{2K} \ge \sup_{s \in [0, h_w]}\big\|r_{\mathrm{model},w}(s)\big\|_2.
\label{eq:cert_sup_res}
\end{equation}
We strictly distinguish: (i) the \textbf{window-level bound} (using $\varepsilon_{\mathrm{mod},w}^{\sup}$ and $\bar{e}_{P,w}$), (ii) the \textbf{seed-level uniform supremum bound} (using $\varepsilon_{\mathrm{mod,sup}}^{(s)} = \max_w \varepsilon_{\mathrm{mod},w}^{\sup}$ and $\bar{e}_{P,\sup}^{(s)} = \max_w \bar{e}_{P,w}$), (iii) the \textbf{global 10-seed worst-case uniform bound} ($\max_s$), and (iv) the \textbf{seed-level RMS diagnostic} ($\mathrm{RMS}_w$, which is an $\ell_2$ population average and never a uniform point-wise guarantee).

\begin{theorem}[Unified Gap Extrapolation Error Bound]
\label{thm:extrap_bound}
Let $\hat{z}^{\mathrm{exact}}(t) = [\hat{q}(t); \hat{p}(t)]$ denote the continuous-time model trajectory of Eq.~\eqref{eq:eom} on $t \in [t_w, t_w + h_w]$ starting from $\hat{z}^{\mathrm{exact}}(t_w) = [q_{k,w}; \dot{q}_{k,w}]$ with $\|\tilde{F}(\hat{q})\|_2 \le L_V + F_{\max}$ ($L_V = d^{-1/2}\|W_{\mathrm{pot}}\|_2, F_{\max} = c_f\sqrt{d}$), and let $z_w^*(t)$ denote the $C^2$ target trajectory~\eqref{eq:c2_target} with certified residual supremum $\varepsilon_{\mathrm{mod},w}^{\sup}$~\eqref{eq:cert_sup_res}. Let $e_{q,w} = \|q_{k,w} - q_w^*(t_w)\|_2$, $e_{v,w} = \|\dot{q}_{k,w} - \dot{q}_w^*(t_w)\|_2$, and $\bar{e}_{P,w} = \sqrt{\alpha_{\mathrm{eff}}e_{q,w}^2 + 2\epsilon e_{q,w}e_{v,w} + e_{v,w}^2} \ge \|e_w(t_w)\|_P$. Define $z_{0,\mathrm{mod},w} = \|\dot{q}_{k,w}\|_2 / \sqrt{\lambda_{\min}(P)}$, $z_{0,\mathrm{tgt},w} = \kappa_P\sqrt{e_{q,w}^2 + \|\dot{q}_w^*(t_w)\|_2^2}$, $R_\infty = \sqrt{\frac{2C_F}{\mu\lambda_{\min}(P)}}$, and $R_{\infty,w}^* = R_\infty\frac{L_V + F_{\max} + \varepsilon_{\mathrm{mod},w}^{\sup}}{L_V + F_{\max}}$, so $\|e_w(t)\|_2 \le \bar{R}_{\mathrm{UUB},w} \triangleq \max(z_{0,\mathrm{mod},w}, R_\infty) + \max(z_{0,\mathrm{tgt},w}, R_{\infty,w}^*)$ on $[t_w, t_w + h_w]$. Because $f_A, f_B \in C^\infty(\mathbb{R}^{2d})$ have bounded derivatives $\|DF_{\mathrm{tot}}\|_2 \le L_F$ and $\|D^2 F_{\mathrm{tot}}\|_2 \le M_{F,2} = \frac{4}{3\sqrt{3}}(\frac{1}{d}\|W_{\mathrm{pot}}\|_2^3 + c_f\beta_q^2)$, the $M$-step Strang-splitting error satisfies the analytical global bound $E_{\mathrm{disc}}(h_w, \delta t) \le E_{\mathrm{disc}}^{\mathrm{BCH}}(h_w, \delta t) \triangleq \frac{e^{L_f h_w}-1}{L_f}c_{\mathrm{loc}}\delta t^2$ (derived in Appendix~\ref{app:proof_thm3}, Eq.~\eqref{eq:bch_bound}).
\begin{enumerate}
    \item \textbf{Small-Gain Contractive Regime ($(\epsilon\gamma + L_{\mathrm{nl,full}})^2 < 2\epsilon(\gamma - \epsilon)(\alpha_{\mathrm{eff}} - L_{\mathrm{nl}}^{(-)})$, Satisfied on $0/10$ Trained Seeds):} With $\eta = \frac{\gamma - \epsilon}{2}$, $c_{q,\mathrm{net}} = \epsilon(\alpha_{\mathrm{eff}} - L_{\mathrm{nl}}^{(-)}) - \frac{(\epsilon\gamma + L_{\mathrm{nl,full}})^2}{2(\gamma - \epsilon)} > 0$, $c_{p,\mathrm{net}} = \frac{\gamma - \epsilon}{2} > 0$, and $\mu_{\mathrm{net}} = \frac{2\min(c_{q,\mathrm{net}}, c_{p,\mathrm{net}})}{\lambda_{\max}(P)} > 0$:
    \begin{align}
    &\big\|\hat{z}_w^{(M)} - z_w^*(t_w + h_w)\big\|_2 \le E_{\mathrm{disc}}^{\mathrm{BCH}}(h_w, \delta t) \nonumber \\
    &\quad + \frac{1}{\sqrt{\lambda_{\min}(P)}}\Bigg( e^{-\frac{1}{2}\mu_{\mathrm{net}} h_w}\bar{e}_{P,w} + \frac{1 - e^{-\frac{1}{2}\mu_{\mathrm{net}} h_w}}{\frac{1}{2}\mu_{\mathrm{net}}}\varepsilon_{\mathrm{mod},w}^{\sup} \Bigg).
    \label{eq:thm3_bound}
    \end{align}
    \item \textbf{Finite-Horizon Young--Gr\"{o}nwall Regime ($(\epsilon\gamma + L_{\mathrm{nl,full}})^2 \ge 2\epsilon(\gamma - \epsilon)(\alpha_{\mathrm{eff}} - L_{\mathrm{nl}}^{(-)})$, Governing $10/10$ Trained Seeds for Both $\alpha_{\mathrm{eff}}=0.35$ and $\alpha_{\mathrm{eff}}=0.10$):} Setting $\eta = \gamma - \epsilon$ yields $K_{\mathrm{Young}} = \frac{(\epsilon\gamma + L_{\mathrm{nl,full}})^2}{4(\gamma - \epsilon)} - \epsilon(\alpha_{\mathrm{eff}} - L_{\mathrm{nl}}^{(-)}) > 0$ and $\nu_{\mathrm{Young}} = \frac{K_{\mathrm{Young}}}{\alpha_{\mathrm{eff}} - \epsilon^2} > 0$, giving the window-level latent tracking bound:
    \begin{align}
    &\big\|\hat{z}_w^{(M)} - z_w^*(t_w + h_w)\big\|_2 \le \bar{e}_{\mathrm{lat},w} \triangleq E_{\mathrm{disc}}^{\mathrm{BCH}}(h_w, \delta t) \nonumber \\
    &\quad + \min\!\Bigg\{\bar{R}_{\mathrm{UUB},w}, \; \frac{1}{\sqrt{\lambda_{\min}(P)}}\Bigg( e^{\nu_{\mathrm{Young}} h_w}\bar{e}_{P,w} \nonumber \\
    &\quad + \frac{e^{\nu_{\mathrm{Young}} h_w} - 1}{\nu_{\mathrm{Young}}}\varepsilon_{\mathrm{mod},w}^{\sup} \Bigg)\Bigg\},
    \label{eq:thm3_gronwall}
    \end{align}
    and the induced operator-spectral RUL bound $|\hat{\mu}_{w+1} - y_w^*(t_w+h_w)| \le \varepsilon_{\mathrm{probe},w} + L_{g,\mathrm{spec}}\bar{e}_{\mathrm{lat},w}$, where $L_{g,\mathrm{spec}} = \sigma_y \|W_{\mathrm{pr1},z}\|_2 \|W_{\mathrm{pr2}}\|_2$. Taking $\max_w$ yields the \textbf{seed-level uniform supremum guarantee} ($\max_{s,w}$ for the \textbf{global 10-seed worst-case bound}), while $\mathrm{RMS}_w$ yields the \textbf{fleet-wide RMS summary diagnostic}.
\\end{enumerate}
\end{theorem}
\emph{Vacuousness of Global Spectral RUL Bounds vs.\ Certified Latent Contraction (Table~\ref{tab:thm3_per_seed}):} See Appendix~\ref{app:proof_thm3} for full proofs and per-seed verification across all 10 seeds:
\begin{itemize}
    \item \textbf{Certified Latent-Space Error Reduction ($60.0\%$ Uniform Supremum, $63.3\%$ RMS):} In Panel~A ($\alpha_{\mathrm{eff}}=0.35, h_k=0.35$, where $\lambda_{\min}(P)=0.34031$ and $\sqrt{\lambda_{\min}(P)}=0.58336$), all 10 seeds satisfy UUB initial inclusion ($z_{0,\mathrm{mod}}^{\max} = 2.84 \pm 0.25 \ll R_\infty = 68.57 \pm 1.55$ and $z_{0,\mathrm{tgt}}^{\max} = 1.39 \pm 0.28 \ll R_\infty^* = 111.03 \pm 5.68$). The analytical BCH discretization bound is $E_{\mathrm{disc}}^{\mathrm{BCH}} = 0.00072 \pm 0.00005$ units (upper-bounding the 400-substep reference difference $\hat{E}_{\mathrm{disc}}^{(400)} = 0.00010 \pm 0.00001$ RMS, $0.00020$ max). Secant velocity alignment ($\mathcal{L}_{\mathrm{kin}}$) reduces the certified latent tracking bound $\bar{e}_{\mathrm{lat}}$ by \textbf{$60.0\%$ on the seed-level uniform supremum} ($14.65 \pm 1.94 \to 5.86 \pm 0.70$ units; global 10-seed worst-case $\max_{s,w}$ reduced from $17.50$ to $7.10$ units) and by \textbf{$63.3\%$ on the RMS summary} ($8.50 \pm 1.64 \to 3.12 \pm 0.39$ units).
    \item \textbf{Vacuousness of Operator-Norm RUL Bounds Relative to $Y_{\max}=125$ Cycles:} Because FD001 RUL is capped at $Y_{\max} = 125$ cycles (so $|\hat{\mu} - y^*| \le 125$ trivially), multiplying $\bar{e}_{\mathrm{lat}}$ by the global operator spectral norm $L_{g,\mathrm{spec}} = 115.30 \pm 6.30\text{ cycles/unit}$ produces RUL bounds—$372.01 \pm 46.99$ cycles on RMS (global max $443.63$) and $734.68 \pm 81.23$ cycles on the seed-level uniform supremum (global max $853.18$)—that \textbf{exceed $125$ cycles and are formally vacuous (non-informative) at the RUL scale}. In Appendix~\ref{app:proof_thm3} (Section~5), we investigate a tighter Duhamel--Volterra variation-of-constants bound that avoids Young's inequality division by $4(\gamma - \epsilon)$ and the Rayleigh factor $1/\sqrt{\lambda_{\min}(P)}$; while this tightens the latent RMS bound by $2.45\times$ (to $1.27 \pm 0.13$ units) and lowers the spectral RUL RMS bound to $159.04 \pm 16.64$ cycles ($334.45 \pm 26.49$ supremum), it \emph{still} exceeds $125$ cycles because $L_{g,\mathrm{spec}}$ is $8.1\times$ larger than the empirical chord sensitivity $\hat{L}_{g,\mathrm{dir}} = 14.27 \pm 1.02\text{ cycles/unit}$ (which gives an empirical plug-in diagnostic of $57.19 \pm 7.50$ cycles vs.\ $134.36 \pm 28.70$ without $\mathcal{L}_{\mathrm{kin}}$). Consequently, Theorem~\ref{thm:extrap_bound} must \emph{not} be interpreted as a standalone RUL safety guarantee; practical RUL-scale uncertainty bounds rely on our validation-calibrated Mondrian conformal predictor (Section~4.5).
\end{itemize}

"""

